#!/usr/bin/env python3
"""FS3 v190 - bomb blasts, a smaller EMP, the new rearm window.

    Blast       A Cyclops goes off over an area as in FS2: full damage out
                to 100 m (40 px), falling to nothing at 200 m (80 px). It
                hits every enemy in reach besides the ship it struck, and
                the player who flew in too close (Silvio: that keeps a
                bomber off its target). An allied bomber's blast spares
                the player. Missiles only ever hit what they hit.
    EMP         Half the FS2 radius: 150 m (60 px) instead of 150 px.
    Rearm       Three columns: your ship and its banks, the weapons the
                chosen bank may carry (with the points still needed), and
                a fixed info panel for the weapon under the pointer: facts,
                bars against hull / shields / subsystems compared with the
                weapon in the bank, what it means on your ship, the keys.
                Reach in screen widths, no metres. Missiles are compared
                as a full bank. Keys: 1-5 bank, up/down and Enter weapon.
                Picking the weapon already in the bank reloads it.

Needs v189. Edits src/ in place, updates the simulations. Run assemble.py
afterwards.
"""
import base64
import os
import sys

if "CAP_HULL_MIN" not in open("src/50_combat.js", encoding="utf-8").read():
    sys.exit("Abbruch: erst v189 einspielen.")
if "BLAST_PX_PER_M" in open("src/56_banks.js", encoding="utf-8").read():
    sys.exit("Abbruch: v190 ist schon eingespielt.")

F = {}
def load(p):
    if p not in F: F[p] = open(p, encoding="utf-8").read()
def rep(p, old, new, count=1):
    load(p)
    n = F[p].count(old)
    if n != count:
        sys.exit("Abbruch (%s): Suchtext %d-mal gefunden, erwartet %d.\n%s" % (p, n, count, old[:200]))
    F[p] = F[p].replace(old, new)
